 function invalid(message='The saved stock update could not be verified. Reopen this original stock record and check its saved update.'){throw Error(message)}

 function markerBinding(receipt){const m=receipt?.original_receiving_recovery;return m?stable([m.serviceOrigin,m.tenantId,m.financialReceiptId,m.tradeId,m.receiptHash,m.physicalIntakeId,m.physicalManifestHash,m.receivingId,m.serverRevision,m.planHash,m.restorationSourceHash,m.proofHash]):''}

 function total(receipt){if(!Array.isArray(receipt?.cards)||!receipt.cards.length||receipt.cards.length>1000)return null;let count=0;const ids=new Set();for(const card of receipt.cards){if(!object(card)||!uuid(card.row_id)||ids.has(card.row_id)||!integer(card.qty,1,100000)||!hash(card.source_line_key)||!price(card.final_price))return null;ids.add(card.row_id);count+=card.qty}return integer(count,1)?count:null}

 function eligible(){return stockManager()&&stockChild(state.receipt)&&stockMarkerValid(state.receipt)&&profile(state.receipt.hosted_receive.label_profile)&&total(state.receipt)!==null&&!state.dirty&&!stockPendingInputs()}

 function anchor(){return stable([state.receipt?.id,state.receipt?.revision,stockAuth(),markerBinding(state.receipt)])}

 function current(c){return !!c&&c===context&&c.id===state.receipt?.id&&c.revision===state.receipt?.revision&&c.auth===stockAuth()&&c.binding===markerBinding(state.receipt)&&eligible()}

 function storageKey(c,prefix=PREFIX){return prefix+encodeURIComponent(stockOrigin)+'/'+encodeURIComponent(c.marker.tenantId)+'/'+encodeURIComponent(c.store)+'/'+encodeURIComponent(c.id)}
 function hasReferenceLock(){return !!navigator.locks&&typeof navigator.locks.request==='function'}
 function storageFailure(){const error=Error('The request reference could not be saved. Saved reminders are read-only in this window; reopen Stock & Sleeve in a supported browser to make changes.');error.referenceStorage=true;return error}
 function referenceChanged(){const error=Error('Another saved reminder changed in a different window. It has been kept. Check that update before continuing.');error.referenceChanged=true;return error}
 function featureUnavailable(error){return ['PROFILE_FEATURE_UPGRADE_REQUIRED','PROFILE_FEATURE_UNAVAILABLE'].includes(error?.code)}
 function parseRef(raw,c){if(raw===null)return null;if(typeof raw!=='string'||new TextEncoder().encode(raw).length>4096)invalid('A saved stock-update reference needs owner review. It has been kept and will not be replaced.');let ref;try{ref=JSON.parse(raw)}catch{invalid('A saved stock-update reference needs owner review. It has been kept and will not be replaced.')}if(!validRef(ref,c))invalid('A saved stock-update reference needs owner review. It has been kept and will not be replaced.');return ref}
 function legacyKnown(c,raw){const value=legacyResolved.get(storageKey(c));return !!value&&value.auth===c.auth&&value.raw===raw&&value.expires>Date.now()}
 function rememberLegacy(c,raw){if(!raw)return;while(legacyResolved.size>=16)legacyResolved.delete(legacyResolved.keys().next().value);legacyResolved.set(storageKey(c),{raw,auth:c.auth,expires:Date.now()+300000})}
 async function referenceLock(c,work){if(!hasReferenceLock()){c.storageUnavailable=true;throw storageFailure()}try{return await navigator.locks.request('ss.original-stock-reference:'+storageKey(c),{mode:'exclusive'},()=>{if(!current(c))throw referenceChanged();return work()})}catch(error){if(error.referenceChanged||error.referenceStorage)throw error;c.storageUnavailable=true;throw storageFailure()}}
 function exactStored(c){const raw=localStorage.getItem(storageKey(c)),legacy=localStorage.getItem(storageKey(c,LEGACY_PREFIX));if(raw!==c.refRaw||legacy!==c.legacyRaw)throw referenceChanged();return {raw,legacy}}

 function validRef(ref,c){return object(ref)&&Object.keys(ref).length===REF_KEYS.length&&Object.keys(ref).every(name=>REF_KEYS.includes(name))&&ref.version===1&&ref.serviceOrigin===stockOrigin&&ref.tenantId===c.marker.tenantId&&ref.store===c.store&&ref.stockReceiptId===c.id&&ref.receivingId===c.marker.receivingId&&ref.serverRevision===c.marker.serverRevision&&ref.planHash===c.marker.planHash&&uuid(ref.intentId)&&key(ref.requestKey)&&KINDS.includes(ref.kind)}

 function readRef(c){let raw,legacy;try{raw=localStorage.getItem(storageKey(c));legacy=localStorage.getItem(storageKey(c,LEGACY_PREFIX))}catch{c.storageUnavailable=true;throw storageFailure()}const ref=parseRef(raw,c),old=parseRef(legacy,c);c.refRaw=raw;c.legacyRaw=legacy;c.legacyConflict=!!ref&&!!old&&!legacyKnown(c,legacy)&&!exact(ref,old);c.refSource=ref?'v2':old&&!legacyKnown(c,legacy)?'legacy':null;c.storageUnavailable=!hasReferenceLock();return ref||(!legacyKnown(c,legacy)?old:null)}

 async function saveRef(c,ref){if(!validRef(ref,c))invalid();return referenceLock(c,()=>{const stored=exactStored(c),old=parseRef(stored.raw,c),legacy=parseRef(stored.legacy,c);if(c.legacyConflict||old&&!exact(old,ref)||legacy&&!legacyKnown(c,stored.legacy)&&!exact(legacy,ref))throw referenceChanged();const raw=JSON.stringify(ref);localStorage.setItem(storageKey(c),raw);if(localStorage.getItem(storageKey(c))!==raw)throw storageFailure();c.refRaw=raw;c.pending=ref;c.refSource='v2';c.storageUnavailable=false;return true})}

